from collections import deque

def comps(g):
 h,w=len(g),len(g[0]); seen=set(); out=[]
 for r in range(h):
  for c in range(w):
   if g[r][c] and (r,c) not in seen:
    q=[(r,c)]; seen.add((r,c)); cells=[]
    while q:
     x,y=q.pop(); cells.append((x,y))
     for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
      z=(x+dx,y+dy)
      if 0<=z[0]<h and 0<=z[1]<w and g[z[0]][z[1]] and z not in seen: seen.add(z);q.append(z)
    rs=[x for x,y in cells];cs=[y for x,y in cells]
    out.append((min(rs),max(rs),min(cs),max(cs),len(cells)))
 return out
for i,g in enumerate((D1,D2,D3,D4),1): print(i,comps(g))

